<template>
<section class="refunds"><header><div><h2>退款管理</h2><p>审核退款申请、核对金额并登记退款结果</p></div><div class="filters"><el-select v-model="status" @change="page=1;load()" style="width:160px"><el-option label="全部" value="all"/><el-option v-for="(label,key) in labels" :key="key" :label="label" :value="key"/></el-select><el-button @click="load" :loading="loading">刷新</el-button></div></header>
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<el-table :data="rows" v-loading="loading" empty-text="暂无退款申请"><el-table-column prop="booking_id" label="订单编号" width="110"/><el-table-column prop="yonghuxingming" label="客户" min-width="100"/><el-table-column prop="sheyingxingming" label="摄影师" min-width="100"/><el-table-column label="申请金额" width="130"><template #default="s">¥ {{Number(s.row.amount).toFixed(2)}}</template></el-table-column><el-table-column prop="reason" label="申请原因" min-width="170" show-overflow-tooltip/><el-table-column label="退款进度" width="150"><template #default="s"><el-tag>{{labels[s.row.status]}}</el-tag></template></el-table-column><el-table-column prop="created_at" label="申请时间" min-width="170"/><el-table-column label="操作" min-width="230" fixed="right"><template #default="s"><el-button link @click="view(s.row)">详情</el-button><template v-if="admin"><el-button v-if="s.row.status==='pending'" link type="primary" @click="handle(s.row,'approve')">批准</el-button><el-button v-if="s.row.status==='pending'" link type="danger" @click="handle(s.row,'reject')">驳回</el-button><el-button v-if="s.row.status==='approved'" link type="primary" @click="handle(s.row,'complete')">登记退款完成</el-button></template></template></el-table-column></el-table>
<el-pagination v-if="total>20" background layout="total,prev,pager,next" :total="total" :page-size="20" v-model:current-page="page" @current-change="load"/>
<el-dialog v-model="visible" :title="action?titles[action]:'退款详情'" width="min(560px,94vw)" append-to-body :close-on-click-modal="!busy"><template v-if="selected"><el-descriptions :column="1" border><el-descriptions-item label="订单编号">#{{selected.booking_id}}</el-descriptions-item><el-descriptions-item label="申请金额">¥ {{Number(selected.amount).toFixed(2)}}</el-descriptions-item><el-descriptions-item label="原因">{{selected.reason}}</el-descriptions-item><el-descriptions-item label="审核说明">{{selected.admin_note||'—'}}</el-descriptions-item><el-descriptions-item label="处理结果">{{selected.result_note||'—'}}</el-descriptions-item><el-descriptions-item label="处理人">{{selected.handled_by||'—'}}</el-descriptions-item><el-descriptions-item label="完成时间">{{selected.completed_at||'—'}}</el-descriptions-item></el-descriptions><el-alert v-if="action==='approve'" title="批准后将取消预约并释放档期，之后仍需登记退款结果。" type="warning" :closable="false" style="margin-top:18px"/><el-form v-if="action" label-position="top" style="margin-top:20px"><el-form-item :label="action==='complete'?'退款结果说明':'审核说明'"><el-input v-model="note" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="请填写处理依据或结果"/></el-form-item></el-form><el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false"/></template><template #footer><el-button :disabled="busy" @click="visible=false">关闭</el-button><el-button v-if="action" type="primary" :loading="busy" @click="submit">确认{{titles[action]}}</el-button></template></el-dialog>
</section>
</template>
<script setup>
import {ref,getCurrentInstance,onMounted} from 'vue'
const ctx=getCurrentInstance().appContext.config.globalProperties,admin=localStorage.getItem('sessionTable')==='users'
const labels={pending:'等待审核',approved:'已批准 · 待退款',rejected:'已驳回',completed:'退款已完成'},titles={approve:'批准退款',reject:'驳回申请',complete:'登记退款完成'}
const rows=ref([]),status=ref('all'),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),visible=ref(false),selected=ref(null),action=ref(''),note=ref(''),busy=ref(false),dialogError=ref('')
async function load(){loading.value=true;error.value='';try{const r=await ctx.$http.get('booking-refunds',{params:{status:status.value,page:page.value}});rows.value=r.data.data;total.value=Number(r.data.total)}catch(e){error.value=e?.data?.msg||e?.message||'退款记录加载失败'}finally{loading.value=false}}
function view(row){selected.value=row;action.value='';dialogError.value='';visible.value=true}
function handle(row,value){view(row);action.value=value;note.value=''}
async function submit(){if(busy.value)return;if(!note.value.trim()){dialogError.value='请填写处理说明';return}busy.value=true;dialogError.value='';try{await ctx.$http.post('booking-refunds/'+selected.value.id+'/'+action.value,{note:note.value.trim()});visible.value=false;ctx.$toolUtil.message('处理完成，已通知用户','success');await load()}catch(e){dialogError.value=e?.data?.msg||e?.message||'处理失败'}finally{busy.value=false}}
onMounted(load)
</script>
<style scoped>.refunds header{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:24px}.refunds h2{margin:0 0 10px;color:#305d4c;font-size:24px}.refunds header p{font-size:13px;color:#85917d;margin:0}.filters{display:flex;gap:10px}.refunds .el-pagination{justify-content:center;margin-top:20px}@media(max-width:700px){.refunds header{display:block}.filters{margin-top:16px}}</style>
